<script setup lang="ts">
import { QrCode, LogIn, LogOut, Download, RefreshCw, Clock3, Link2, Printer, UsersRound } from '@lucide/vue'
import { attendanceClock, attendanceDate, attendanceHours, attendanceQrContext, qrAttendanceLink } from '../domain/attendance'
import { orderedDoctors } from '../domain/doctor-roster'
import { formatHours, monthLabel, prettyDate } from '../domain/calendar'
import { attendanceCsv, attendanceQrSvg } from '../services/attendance-exports'
import { downloadText } from '../services/exports'

const w = useWorkspace(), a = useAttendance(), route = useRoute(), { notify } = useNotifications()
const origin = ref(''), svg = ref(''), qrError = ref(''), selectedDate = ref(''), doctorId = ref(''), userId = ref(''), rotateModal = ref(false), unbindId = ref('')
const timezone = computed(() => w.data.value?.settings.timezone ?? 'Asia/Makassar')
const clock = (value: string | null) => attendanceClock(value, timezone.value)
const today = computed(() => attendanceDate(a.now.value, timezone.value))
const scan = computed(() => attendanceQrContext(route.query, w.id.value))
const markToken = computed(() => scan.value.scanned ? scan.value.token : a.token.value)
const qrUrl = computed(() => origin.value && a.token.value && w.mode === 'supabase' ? qrAttendanceLink(origin.value, w.id.value, a.token.value) : '')
const qrImage = computed(() => svg.value ? `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg.value)}` : '')
const doctorList = computed(() => orderedDoctors(w.data.value?.doctors.filter(d => d.active) ?? []))
const completedHours = computed(() => a.records.value.reduce((n, r) => n + (attendanceHours(r) ?? 0), 0))
const disabled = computed(() => a.busy.value || a.loading.value || !!a.error.value || w.loading.value)
const myDuty = computed(() => a.duties.value.find(d => d.date === selectedDate.value))
const accountEmail = (id: string) => a.members.value.find(m => m.userId === id)?.email ?? 'Akun terhubung'
const doctorName = (id: string) => w.data.value?.doctors.find(d => d.id === id)?.name ?? 'Dokter'
let qrRequest = 0
onMounted(() => { origin.value = window.location.origin })
onBeforeUnmount(() => { qrRequest++ })
watch(qrUrl, async url => {
  const request = ++qrRequest
  svg.value = ''; qrError.value = ''
  if (!url) return
  try { const result = await attendanceQrSvg(url); if (request === qrRequest) svg.value = result }
  catch { if (request === qrRequest) qrError.value = 'QR belum dapat digambar. Coba muat ulang absensi.' }
})
watch(() => a.duties.value, duties => { if (!duties.some(d => d.date === selectedDate.value)) selectedDate.value = duties[0]?.date ?? '' }, { immediate: true })
async function mark(action: 'masuk' | 'pulang') {
  const date = action === 'pulang' ? a.myOpen.value?.duty_date : myDuty.value?.date
  if (markToken.value && date && !disabled.value) await a.mark(markToken.value, action, date)
}
async function bind() { if (doctorId.value && userId.value && await a.bind(doctorId.value, userId.value)) { doctorId.value = ''; userId.value = '' } }
async function rotate() { if (await a.rotate()) rotateModal.value = false }
async function unbind() { if (unbindId.value && await a.unbind(unbindId.value)) unbindId.value = '' }
function exportCsv() { downloadText(attendanceCsv(a.records.value, timezone.value), `Absensi_${w.activeMonth.value}.csv`, 'text/csv;charset=utf-8') }
function downloadQr() { if (svg.value) downloadText(svg.value, 'QR_Absensi_Ruang_Dinas.svg', 'image/svg+xml') }
function printQr() { window.print() }
async function copyLink() { try { await navigator.clipboard.writeText(qrUrl.value); notify('Tautan QR disalin.') } catch { notify('Tautan belum dapat disalin. Gunakan unduhan QR.', true) } }
</script>

<template>
  <div class="screen-only">
    <PageHeading title="Absensi dokter" subtitle="Catat masuk dan pulang sesuai dinas, lalu pantau kehadiran bulanan." eyebrow="Kehadiran tim"><MonthSelect /><button class="btn btn-secondary" :disabled="disabled || w.mode !== 'supabase'" @click="a.load()"><RefreshCw :size="15" :class="a.loading.value ? 'animate-spin' : ''" />Muat ulang</button></PageHeading>
    <section class="app-hero mb-6 flex flex-col justify-between gap-6 rounded-[1.5rem] p-6 text-white sm:flex-row sm:items-center sm:p-8"><div><p class="text-[11px] font-medium tracking-widest text-brand-300">SATU QR UNTUK TIM DOKTER</p><h2 class="mt-3 text-2xl font-semibold tracking-tight">Absen dinas, dari ponsel Anda.</h2><p class="mt-3 max-w-xl text-sm leading-relaxed text-white/60">Pindai QR fasilitas, masuk dengan akun sendiri, kemudian catat kedatangan atau kepulangan.</p></div><div class="shrink-0 rounded-2xl border border-white/10 bg-white/5 px-6 py-5"><p class="text-[10px] tracking-wider text-white/60">WAKTU FASILITAS</p><p class="mt-2 text-3xl font-medium tabular-nums text-lime-soft">{{ clock(a.now.value.toISOString()) }}</p><p class="mt-2 text-[11px] text-white/55">{{ prettyDate(today) }}</p></div></section>
    <section v-if="w.mode !== 'supabase'" class="panel p-8"><QrCode :size="28" class="text-brand-600" /><h2 class="mt-4 text-lg font-semibold">Siapkan absensi untuk tim</h2><p class="mt-3 max-w-2xl text-sm leading-relaxed text-slate-600">Absensi QR bersama tersedia pada mode Supabase. Aktifkan penyimpanan bersama dan jalankan migrasi absensi, lalu admin dapat menghubungkan akun dokter serta mengunduh QR fasilitas.</p></section>
    <template v-else>
      <div v-if="a.error.value" role="alert" class="mb-6 rounded-2xl border border-rose-200 bg-rose-50 p-5 text-sm leading-relaxed text-rose-700">{{ a.error.value }}</div>
      <div v-if="scan.error" role="alert" class="mb-6 rounded-2xl border border-amber-200 bg-amber-50 p-5 text-sm leading-relaxed text-amber-800">{{ scan.error }}</div>
      <div class="mb-6 grid gap-4 sm:grid-cols-3"><div v-for="card in [{ label: w.role.value === 'viewer' ? 'Catatan Anda' : 'Catatan kehadiran', value: a.records.value.length, unit: 'dinas', note: monthLabel(w.activeMonth.value) }, { label: 'Belum absen pulang', value: a.open.value.length, unit: 'dokter', note: 'Termasuk dinas lintas bulan' }, { label: 'Total jam kehadiran', value: formatHours(completedHours), unit: 'jam', note: 'Hanya catatan masuk–pulang lengkap' }]" :key="card.label" class="panel p-5"><p class="text-xs text-slate-500">{{ card.label }}</p><p class="mt-4 text-3xl font-semibold tracking-tight tabular-nums">{{ card.value }}<span class="ml-2 text-xs font-normal text-slate-500">{{ card.unit }}</span></p><p class="mt-3 text-[11px] text-slate-500">{{ card.note }}</p></div></div>
      <div class="grid items-start gap-6" :class="w.isAdmin.value ? 'xl:grid-cols-[1.2fr_0.8fr]' : ''">
        <section class="panel p-6"><div class="flex items-center justify-between"><h2 class="font-semibold">Absen Anda</h2><span class="tag bg-brand-50 text-brand-700">{{ a.myDoctor.value?.name || a.myOpen.value?.doctor_name || 'Akun pengguna' }}</span></div>
          <p v-if="a.loading.value" class="mt-5 text-sm text-slate-500" role="status">Memuat catatan kehadiran…</p>
          <p v-else-if="!a.myDoctor.value && !a.myOpen.value" class="mt-5 text-sm leading-relaxed text-slate-600">Akun ini belum dihubungkan ke dokter. Admin dapat memasangkannya pada bagian “Akun dokter”.</p>
          <template v-else>
            <div v-if="a.myOpen.value" class="mt-5 rounded-2xl bg-brand-50 p-5"><p class="text-[11px] font-medium text-brand-700">DINAS SEDANG BERJALAN</p><h3 class="mt-2 text-xl font-semibold">{{ a.myOpen.value.shift_code }} · {{ a.myOpen.value.scheduled_hours }} jam terjadwal</h3><p class="mt-2 text-sm text-slate-600">Tanggal dinas {{ prettyDate(a.myOpen.value.duty_date) }} · masuk {{ clock(a.myOpen.value.check_in) }}</p><button class="btn btn-primary mt-5 w-full" :disabled="disabled || !markToken" @click="mark('pulang')"><LogOut :size="16" />Catat pulang</button></div>
            <div v-else class="mt-5 space-y-4"><div v-if="a.duties.value.length"><label for="attendance-duty" class="label">Dinas yang dapat diabsen sekarang</label><select id="attendance-duty" v-model="selectedDate" class="field" :disabled="disabled"><option v-for="d in a.duties.value" :key="d.date" :value="d.date">{{ prettyDate(d.date) }} · {{ d.code }} · {{ d.hours }} jam</option></select></div><p v-else class="rounded-xl bg-slate-50 p-4 text-sm leading-relaxed text-slate-600">Belum ada dinas yang bisa diabsen masuk saat ini, atau dinas tersebut sudah tercatat. Periksa jadwal dan muat ulang catatan.</p><button class="btn btn-primary w-full" :disabled="disabled || !markToken || !myDuty" @click="mark('masuk')"><LogIn :size="16" />Catat masuk</button></div>
            <p v-if="!markToken && !scan.error" class="mt-4 text-xs leading-relaxed text-amber-700">Pindai QR yang ditempel di fasilitas untuk mengaktifkan tombol absen.</p>
            <p class="mt-4 text-xs leading-relaxed text-slate-500">Absen masuk dibuka 2 jam sebelum dinas hingga sebelum jam selesai. Waktu pencatatan ditentukan server. Dinas malam tetap memakai tanggal mulai dinas.</p>
          </template>
        </section>
        <section v-if="w.isAdmin.value" class="panel p-6 text-center"><div class="flex items-center justify-center gap-2 text-brand-700"><QrCode :size="18" /><h2 class="font-semibold">QR absensi bersama</h2></div><p class="mt-2 text-xs leading-relaxed text-slate-500">Unduh atau cetak, kemudian tempel di fasilitas.</p><img v-if="qrImage" :src="qrImage" alt="QR untuk membuka absensi fasilitas" class="mx-auto my-5 w-full max-w-64 rounded-xl border border-slate-100" width="512" height="512" /><div v-else class="mx-auto my-5 flex aspect-square max-w-64 items-center justify-center rounded-xl bg-slate-50 text-sm text-slate-500">{{ a.loading.value ? 'Menyiapkan QR…' : 'QR belum tersedia' }}</div><p v-if="qrError" role="alert" class="mb-4 text-xs text-rose-700">{{ qrError }}</p><div class="flex flex-wrap justify-center gap-2"><button class="btn btn-primary" :disabled="!svg || disabled" @click="downloadQr"><Download :size="14" />Unduh QR</button><button class="btn btn-secondary" :disabled="!svg || disabled" @click="printQr"><Printer :size="14" />Cetak</button><button class="btn btn-secondary" :disabled="!qrUrl || disabled" @click="copyLink"><Link2 :size="14" />Salin tautan</button></div><button class="mt-4 text-xs font-medium text-slate-500 underline underline-offset-4" :disabled="disabled || !a.token.value" @click="rotateModal = true">Ganti QR fasilitas</button></section>
      </div>
      <section class="panel mt-6 overflow-hidden"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 px-6 py-5"><div><h2 class="font-semibold">Catatan kehadiran</h2><p class="mt-1 text-xs text-slate-500">{{ monthLabel(w.activeMonth.value) }} · {{ w.role.value === 'viewer' ? 'catatan akun Anda' : 'tim pelayanan' }}</p></div><button class="btn btn-secondary" :disabled="disabled || !a.records.value.length" @click="exportCsv"><Download :size="14" />Ekspor CSV</button></div><div class="scrollbar-thin overflow-x-auto"><table class="w-full text-sm"><thead class="table-head"><tr><th class="px-6 py-4">Tanggal dinas</th><th class="px-4 py-4">Dokter</th><th class="px-4 py-4">Kode</th><th class="px-4 py-4 text-center">Jam jadwal</th><th class="px-4 py-4 text-center">Masuk</th><th class="px-4 py-4 text-center">Pulang</th><th class="px-4 py-4 text-center">Jam hadir</th><th class="px-4 py-4">Status</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="r in a.records.value" :key="r.id"><td class="whitespace-nowrap px-6 py-4 text-xs text-slate-600">{{ prettyDate(r.duty_date) }}</td><td class="whitespace-nowrap px-4 py-4 font-medium">{{ r.doctor_name }}</td><td class="px-4 py-4 text-xs text-brand-700">{{ r.shift_code }}</td><td class="px-4 py-4 text-center tabular-nums">{{ formatHours(r.scheduled_hours) }}</td><td class="px-4 py-4 text-center tabular-nums">{{ clock(r.check_in) }}</td><td class="px-4 py-4 text-center tabular-nums">{{ clock(r.check_out) }}</td><td class="px-4 py-4 text-center font-semibold tabular-nums">{{ r.check_out ? formatHours(attendanceHours(r)) : '—' }}</td><td class="px-4 py-4"><span class="tag whitespace-nowrap" :class="r.check_out ? 'bg-brand-50 text-brand-700' : 'bg-amber-50 text-amber-700'">{{ r.check_out ? 'Selesai' : 'Belum pulang' }}</span></td></tr><tr v-if="!a.records.value.length"><td colspan="8" class="p-8 text-center text-sm text-slate-500">{{ a.loading.value ? 'Memuat catatan…' : 'Belum ada catatan kehadiran pada bulan ini.' }}</td></tr></tbody></table></div><p class="border-t border-slate-100 bg-slate-50/70 px-6 py-4 text-xs leading-relaxed text-slate-500">Jam hadir dihitung dari waktu masuk sampai pulang, termasuk jeda di dalamnya. Jam jadwal mengikuti durasi dinas. Ekspor CSV menyertakan tanggal dan waktu lengkap untuk dinas lintas tengah malam.</p></section>
      <section v-if="w.isAdmin.value" class="panel mt-6 p-6"><div class="flex items-center gap-2"><UsersRound :size="18" class="text-brand-600" /><h2 class="font-semibold">Akun dokter</h2></div><p class="mt-3 text-sm leading-relaxed text-slate-600">Setiap dokter mendaftar dan memverifikasi email. Tambahkan akunnya melalui <NuxtLink to="/pengaturan" class="font-medium text-brand-700 underline underline-offset-4">Pengaturan → Hak akses</NuxtLink>, lalu hubungkan ke nama dokter di sini.</p><form class="mt-5 grid items-end gap-3 md:grid-cols-[1fr_1fr_auto]" @submit.prevent="bind"><div><label for="account-doctor" class="label">Dokter</label><select id="account-doctor" v-model="doctorId" class="field" required :disabled="disabled"><option value="" disabled>Pilih dokter</option><option v-for="d in doctorList" :key="d.id" :value="d.id" :disabled="a.accounts.value.some(link => link.doctor_id === d.id)">{{ d.name }}</option></select></div><div><label for="account-user" class="label">Akun anggota</label><select id="account-user" v-model="userId" class="field" required :disabled="disabled"><option value="" disabled>Pilih email akun</option><option v-for="member in a.members.value" :key="member.userId" :value="member.userId" :disabled="a.accounts.value.some(link => link.user_id === member.userId)">{{ member.email }}</option></select></div><button class="btn btn-primary" :disabled="disabled || !doctorId || !userId">Hubungkan</button></form><div class="mt-5 divide-y divide-slate-100"><div v-for="link in a.accounts.value" :key="link.doctor_id" class="flex flex-wrap items-center justify-between gap-3 py-3"><div><p class="text-sm font-medium">{{ doctorName(link.doctor_id) }}</p><p class="mt-1 text-xs text-slate-500">{{ accountEmail(link.user_id) }}</p></div><button class="btn btn-quiet text-xs" :disabled="disabled" @click="unbindId = link.doctor_id">Lepas tautan</button></div><p v-if="!a.accounts.value.length" class="py-3 text-xs text-slate-500">Belum ada akun dokter yang dihubungkan.</p></div></section>
    </template>
  </div>
  <article v-if="qrImage" class="attendance-qr-print hidden text-center print:block"><p class="text-sm font-medium">{{ w.data.value?.settings.hospital }}</p><h1 class="mt-5 text-3xl font-semibold">ABSENSI DOKTER</h1><p class="mt-3">Pindai QR menggunakan kamera ponsel.</p><img :src="qrImage" alt="QR absensi fasilitas" class="mx-auto my-8 w-[130mm]" width="512" height="512" /><p>Masuk dengan akun Anda, lalu pilih Catat masuk atau Catat pulang.</p><p class="mt-5 text-sm">Ruang Dinas · Satu QR untuk tim pelayanan</p></article>
  <AppModal v-if="rotateModal" title="Ganti QR fasilitas?" @close="!a.busy.value && (rotateModal = false)"><p class="text-sm leading-relaxed text-slate-600">QR lama akan berhenti berlaku, termasuk untuk absen pulang. Unduh dan tempel QR baru setelah penggantian.</p><div class="mt-6 flex justify-end gap-2"><button class="btn btn-secondary" :disabled="a.busy.value" @click="rotateModal = false">Batal</button><button class="btn btn-primary" :disabled="a.busy.value" @click="rotate">Ganti QR</button></div></AppModal>
  <AppModal v-if="unbindId" title="Lepaskan akun dokter?" @close="!a.busy.value && (unbindId = '')"><p class="text-sm leading-relaxed text-slate-600">Akun yang terhubung ke {{ doctorName(unbindId) }} akan kehilangan akses untuk mencatat absen dokter ini. Selesaikan absen pulang terlebih dahulu. Catatan lama tetap tersimpan.</p><div class="mt-6 flex justify-end gap-2"><button class="btn btn-secondary" :disabled="a.busy.value" @click="unbindId = ''">Batal</button><button class="btn btn-primary" :disabled="a.busy.value" @click="unbind">Lepaskan</button></div></AppModal>
</template>
